<template>
	<transition name="soft-dialog-pop">
		<view
			v-if="visible"
			class="soft-dialog-mask"
			@touchmove.stop.prevent
			@click="handleMaskClick"
		>
			<view class="soft-dialog" @click.stop>
				<view class="soft-dialog-rail"></view>
				<text v-if="title" class="soft-dialog-title">{{ title }}</text>
				<text class="soft-dialog-content">{{ content }}</text>
				<view class="soft-dialog-actions">
					<view
						v-if="showCancel"
						class="soft-dialog-btn soft-dialog-btn-secondary"
						@click="handleCancel"
					>
						{{ cancelText }}
					</view>
					<view class="soft-dialog-btn soft-dialog-btn-primary" @click="handleConfirm">
						{{ confirmText }}
					</view>
				</view>
			</view>
		</view>
	</transition>
</template>

<script>
export default {
	name: 'SoftDialog',
	props: {
		visible: { type: Boolean, default: false },
		title: { type: String, default: '' },
		content: { type: String, default: '' },
		confirmText: { type: String, default: '确定' },
		cancelText: { type: String, default: '取消' },
		showCancel: { type: Boolean, default: true },
		maskClosable: { type: Boolean, default: true }
	},
	methods: {
		handleMaskClick() {
			if (!this.maskClosable) return;
			this.$emit('cancel');
		},
		handleCancel() {
			this.$emit('cancel');
		},
		handleConfirm() {
			this.$emit('confirm');
		}
	}
};
</script>

<style lang="scss" scoped>
.soft-dialog-mask {
	position: fixed;
	inset: 0;
	z-index: 9998;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: 64rpx 56rpx;
	box-sizing: border-box;
	background: rgba(28, 20, 50, 0.42);
	backdrop-filter: blur(8rpx);
	-webkit-backdrop-filter: blur(8rpx);
}

.soft-dialog {
	position: relative;
	width: 100%;
	max-width: 580rpx;
	padding: 44rpx 38rpx 32rpx;
	box-sizing: border-box;
	border-radius: 28rpx;
	background:
		linear-gradient(180deg, rgba(255, 250, 253, 0.97), rgba(255, 255, 255, 0.98));
	border: 1rpx solid rgba(238, 220, 235, 0.92);
	box-shadow:
		0 26rpx 64rpx rgba(45, 28, 60, 0.18),
		inset 0 1rpx 0 rgba(255, 255, 255, 1);
	transform-origin: center center;
}

.soft-dialog-rail {
	position: absolute;
	top: 22rpx;
	left: 50%;
	transform: translateX(-50%);
	width: 56rpx;
	height: 6rpx;
	border-radius: 999rpx;
	background: rgba(212, 104, 138, 0.32);
}

.soft-dialog-title {
	display: block;
	margin-top: 14rpx;
	color: #352238;
	font-size: 30rpx;
	font-weight: 800;
	line-height: 1.32;
	text-align: center;
}

.soft-dialog-content {
	display: block;
	margin-top: 16rpx;
	color: #6a5566;
	font-size: 25rpx;
	line-height: 1.6;
	letter-spacing: 0.5rpx;
	text-align: center;
	word-break: break-word;
}

.soft-dialog-actions {
	display: flex;
	gap: 16rpx;
	margin-top: 32rpx;
}

.soft-dialog-btn {
	flex: 1;
	display: flex;
	align-items: center;
	justify-content: center;
	height: 74rpx;
	border-radius: 999rpx;
	font-size: 27rpx;
	font-weight: 700;
	letter-spacing: 1rpx;
	transition: transform 0.18s ease;
}

.soft-dialog-btn:active {
	transform: scale(0.97);
}

.soft-dialog-btn-secondary {
	color: #8a6a8a;
	background: rgba(255, 239, 246, 0.92);
	border: 1rpx solid rgba(232, 210, 230, 0.92);
}

.soft-dialog-btn-primary {
	color: #ffffff;
	background: linear-gradient(135deg, #ff8ba7, #d4688a);
	box-shadow: 0 12rpx 26rpx rgba(212, 104, 138, 0.26);
}

.soft-dialog-pop-enter-active {
	transition:
		opacity 260ms ease-out;
}

.soft-dialog-pop-leave-active {
	transition:
		opacity 200ms ease-in;
}

.soft-dialog-pop-enter-active .soft-dialog {
	transition:
		transform 320ms cubic-bezier(0.2, 0.72, 0.3, 1.08),
		opacity 280ms ease-out;
}

.soft-dialog-pop-leave-active .soft-dialog {
	transition:
		transform 240ms cubic-bezier(0.4, 0, 0.6, 1),
		opacity 200ms ease-in;
}

.soft-dialog-pop-enter,
.soft-dialog-pop-leave-to {
	opacity: 0;
}

.soft-dialog-pop-enter .soft-dialog,
.soft-dialog-pop-leave-to .soft-dialog {
	opacity: 0;
	transform: translateY(28rpx) scale(0.94);
}

.soft-dialog-pop-enter-to,
.soft-dialog-pop-leave {
	opacity: 1;
}

.soft-dialog-pop-enter-to .soft-dialog,
.soft-dialog-pop-leave .soft-dialog {
	opacity: 1;
	transform: translateY(0) scale(1);
}
</style>
